OUTPUT = '/root/project_proposal_ready.hwpx'

# Extract and verify
print("=== Validating /root/project_proposal_ready.hwpx ===\n")

with zipfile.ZipFile(OUTPUT, 'r') as zf:
    for name in sorted(zf.namelist()):
        print(f'=== {name} ===')
        content = zf.read(name).decode('utf-8')

        # Check for remaining placeholders
        placeholders = re.findall(r'\{\{[^}]*\}\}', content)
        if placeholders:
            print(f'ERROR: remaining placeholders: {placeholders}')
        else:
            print('OK: No remaining placeholders')

        # Check for 개월 (month spans)
        months = re.findall(r'\d+\uac1c\uc6d4', content)
        if months:
            print(f'OK: Month spans found: {months}')
        else:
            print('WARNING: No month spans found')

        # Check for linesegarray
        if 'linesegarray' in content.lower():
            print('ERROR: linesegarray still present!')
        else:
            print('OK: No linesegarray elements')

        # Show 단계 lines
        phases = re.findall(r'\ub2e8\uacc4\d[^<]*', content)
        if phases:
            print(f'Phase lines:')
            for p in phases:
